# Keep unlike datasets/settings separate; do not manufacture an aggregate
# intelligence score by pooling authored pilots, public tests and kernel checks.
using JSON3, SHA

function intelligence_evidence_status(payload;superseded=false)
    superseded && return "superseded_pre_output"
    payload===nothing && return "not_scored"
    hasproperty(payload,:complete) && !payload.complete && return "in_progress"
    if hasproperty(payload,:rows)
        any(row->hasproperty(row,:status) && row.status in ("pending","interrupted_attempt"),payload.rows) &&
            return "in_progress"
    end
    "recorded"
end

